/// Aggregate-only result of one bounded two-hop relay probe round.
///
/// [TWO-HOP-PROBE-OUTCOME 2026-07-31 by Codex] These dimensions intentionally
/// remain independent:
/// - `attempted` drives the background cooldown after network work;
/// - `route_accepted` preserves rolling-upgrade control-path compatibility;
/// - `terminal_delivery_verified` requires a fresh terminal-signed receipt and
///   is the only condition that may satisfy operator smoke `success`.
///
/// Never add selected hops, node ids, endpoints, route ids, receiver keys,
/// payloads, or client metadata to this type.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct TwoHopBlindRelayProbeOutcome {
    attempted: bool,
    route_accepted: bool,
    terminal_delivery_verified: bool,
}

/// Aggregate-only result of one authenticated App/client onion relay round.
///
/// [CLIENT-ONION-PARTIAL-SUCCESS 2026-07-31 by Codex] A valid terminal-signed
/// receipt is a hard delivery boundary even when another independently chosen
/// replica fails. The caller may retry replica durability later, but it must
/// not expose the same envelope to the legacy direct peer relay after any
/// terminal has already accepted the exact opaque payload.
///
/// Never add selected hops, route ids, message ids, sender/receiver keys,
/// endpoints, payload commitments, ciphertext, or client metadata here.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct AuthenticatedChatOnionRelayOutcome {
    attempted_paths: usize,
    verified_receipts: usize,
    /// First exact terminal receipt retained only for the requesting client.
    /// Never persist or export it through aggregate node health.
    first_terminal_receipt: Option<BlindRelayDeliveryReceipt>,
}

/// Whether an onion-route failure can safely affect first-hop reputation.
///
/// [ONION-FAILURE-ATTRIBUTION 2026-08-11 by Codex] HTTP transport, status,
/// and malformed first-hop responses are observable at the selected endpoint.
/// A missing or invalid terminal receipt is different: the source cannot tell
/// whether the middle, a later hop, or the terminal caused it. Treating that
/// ambiguous evidence as a first-hop fault lets a malicious downstream node
/// degrade or quarantine an honest middle.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OnionRouteFailureAttribution {
    FirstHop,
    EndToEnd,
}

/// Bounded local failure from authenticated onion request construction.
///
/// [ONION-REQUEST-BUILD-ERROR 2026-08-29 by Codex] This type preserves route
/// admission semantics until the aggregate operator boundary. It never carries
/// payload bytes, route ids, descriptors, endpoints, or node identities.
#[derive(Debug)]
enum OnionRequestBuildError {
    PayloadEncoding,
    RoutePlan(OnionRoutePlanError),
}

impl OnionRequestBuildError {
    #[must_use]
    const fn reason_bucket(&self) -> &'static str {
        match self {
            Self::PayloadEncoding => "onion_payload_encoding_failed",
            Self::RoutePlan(error) => match error.disposition() {
                OnionRouteFailureDisposition::RefreshRoute => "onion_route_refresh_required",
                OnionRouteFailureDisposition::PolicyRejected => "onion_route_policy_rejected",
                OnionRouteFailureDisposition::LocalConstructionFailed => {
                    "onion_route_local_construction_failed"
                }
            },
        }
    }
}

impl AuthenticatedChatOnionRelayOutcome {
    #[must_use]
    fn delivered(&self) -> bool {
        self.verified_receipts > 0
    }

    #[must_use]
    fn fully_replicated(&self) -> bool {
        self.attempted_paths > 0 && self.attempted_paths == self.verified_receipts
    }

    /// Whether compatibility direct relay can run without widening a route
    /// surface that already observed this exact opaque envelope.
    ///
    /// [ONION-FALLBACK-PRIVACY 2026-08-15 by Codex] A lost or invalid receipt
    /// does not prove the attempted middle/terminal failed to observe or store
    /// the payload. Only a preflight outcome with zero network attempts may
    /// safely enter the compatibility path; otherwise local pending storage
    /// preserves retry availability without immediate correlation expansion.
    #[must_use]
    fn compatibility_direct_fallback_allowed(&self) -> bool {
        self.attempted_paths == 0
    }
}

/// Public IP services should return one textual IP address and whitespace.
const PUBLIC_IP_RESPONSE_MAX_BYTES: usize = 256;

/// Gossip is bounded independently from the operator's peer-store capacity.
const DISCOVERY_GOSSIP_RESPONSE_MAX_BYTES: usize = 1024 * 1024;
/// Capability negotiation reads only the compact public discovery summary.
const DISCOVERY_NEGOTIATION_SUMMARY_MAX_BYTES: usize = 64 * 1024;
/// [PURPOSE-BOUND-RECEIPT-NEGOTIATION 2026-08-10 by Codex] Unsigned capability
/// hints must never stall route proof or legacy fallback.
const DISCOVERY_NEGOTIATION_HINT_TIMEOUT: Duration = Duration::from_secs(2);
/// At most two producer-diverse alternates follow exact-evidence misses.
const DIRECTORY_GOSSIP_PROOF_CANDIDATE_LIMIT: usize = 3;

/// Bootstrap/cache snapshots may contain thousands of signed descriptors.
const DISCOVERY_SNAPSHOT_MAX_BYTES: usize = 8 * 1024 * 1024;

/// Build the bounded PeerStore projection sent in the management heartbeat.
///
/// [BOUNDED-DISCOVERY-HEARTBEAT 2026-08-02 by Codex] Full route candidates,
/// per-peer health rows, and audit rings remain available from the local node
/// API. Repeating them in every heartbeat caused the backend's 64 KiB safety
/// gate to reject the entire discovery snapshot. This projection keeps the
/// aggregate contracts consumed by nodeboard while excluding those heavy
/// local diagnostics. Never add endpoints, full node ids, route ids, payloads,
/// receiver identities, client IPs, or user traffic here.
fn peer_store_heartbeat_status_value(status: &PeerStoreStatus) -> serde_json::Value {
    serde_json::json!({
        "snapshot": &status.snapshot,
        "runtime": &status.runtime,
        "blind_relay_quality": &status.blind_relay_quality,
        "two_hop_path_proof_history": &status.two_hop_path_proof_history,
        "three_hop_path_proof_history": &status.three_hop_path_proof_history,
        "max_peers": status.max_peers,
        "recent_peer_events": &status.recent_peer_events,
        "bootstrap": &status.bootstrap,
        "stability": &status.stability,
        "route_governance": &status.route_governance,
        "peer_quorum": &status.peer_quorum,
        "network_story": &status.network_story,
    })
}

/// Builds the bounded discovery object carried by the signed management heartbeat.
///
/// [RECOVERY-ANCHOR-HEARTBEAT 2026-08-21 by Codex] Keep all derived readiness
/// in shared API helpers so the local status endpoint and backend heartbeat
/// cannot disagree about external-witness generation alignment. The signed
/// peer-record batch is intentionally passed in after its own bounded export;
/// this function must not add local audit rows, route candidates, witness
/// identities/endpoints, anchor material, or user traffic.
fn discovery_heartbeat_status_value(
    generated_at: u64,
    status: &PeerStoreStatus,
    local_capabilities: &DiscoveryLocalCapabilityStatus,
    signed_peer_records: PeerStoreSignedPeerRecordsStatus,
) -> serde_json::Value {
    serde_json::json!({
        "generated_at": generated_at,
        "peer_store": peer_store_heartbeat_status_value(status),
        "route_governance": &status.route_governance,
        "blind_relay_runtime": blind_relay_runtime_status_value(
            generated_at,
            status,
            local_capabilities,
        ),
        "recovery_anchor": recovery_anchor_status_value(status),
        "signed_peer_records": signed_peer_records,
        "local_capabilities": local_capabilities,
        "discovery_readiness": discovery_readiness_status_value(status, local_capabilities),
        "source": "rust_peer_store",
        "privacy_boundary": "aggregate node discovery, blind relay, and recovery-anchor state plus bounded signed node-level discovery descriptors for central verification; no client IPs, destinations, DNS contents, packet payloads, chat plaintext, voucher secrets, private keys, or wallet-level traffic"
    })
}

/// Minimal additive fields read from a peer's public discovery summary.
///
/// [DIRECTORY-GOSSIP-NEGOTIATION 2026-07-27 by Codex] This unsigned document
/// is only a transport optimization hint. A false positive can at most cause
/// one optional proof request before mandatory legacy fallback; a false
/// negative can only suppress that optional request. It never grants trust.
#[derive(Debug, Default, serde::Deserialize)]
struct DiscoveryNegotiationSummary {
    #[serde(default)]
    protocol_features: DiscoveryNegotiationFeatures,
}

#[derive(Debug, Default, serde::Deserialize)]
struct DiscoveryNegotiationFeatures {
    #[serde(default)]
    directory_descriptor_proof_gossip_v1: bool,
    /// Whether this relay accepts a terminal receipt propagated through more
    /// than one middle hop. Missing means legacy/unsupported.
    #[serde(default)]
    multihop_delivery_receipt_v1: bool,
    /// Whether current terminal ACKs commit to both payload and canonical
    /// route purpose. Missing means v1-only/unsupported.
    #[serde(default)]
    purpose_bound_delivery_receipt_v2: bool,
}

/// Terminal result for optional Directory-authenticated proof transmission.
///
/// [DIRECTORY-GOSSIP-RELIABILITY 2026-07-28 by Codex] Buckets are stable and
/// privacy-safe. They intentionally omit peer, endpoint, producer, descriptor,
/// block, proof, route, message, payload, client, and traffic dimensions.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
enum DirectoryProofGossipResult {
    #[default]
    NotAttempted,
    Accepted,
    EvidenceRejected,
    ReplicaUnavailable,
    RateLimited,
    ProtocolRejected,
    TransportFailed,
}

impl DirectoryProofGossipResult {
    const fn from_http_status(status: reqwest::StatusCode) -> Self {
        match status {
            reqwest::StatusCode::UNPROCESSABLE_ENTITY => Self::EvidenceRejected,
            reqwest::StatusCode::SERVICE_UNAVAILABLE => Self::ReplicaUnavailable,
            reqwest::StatusCode::TOO_MANY_REQUESTS => Self::RateLimited,
            _ => Self::ProtocolRejected,
        }
    }
}

/// Capability-negotiation stage for one optional proof exchange.
///
/// A typed stage prevents impossible boolean combinations such as "attempted
/// but not capable" from entering round telemetry.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
enum DirectoryProofGossipPeerState {
    #[default]
    NotChecked,
    LegacyOnly,
    NegotiationFailed,
    Attempted,
}

/// Per-peer result for the optional Directory-authenticated gossip frames.
///
/// [DIRECTORY-GOSSIP-RELIABILITY 2026-07-28 by Codex] This is process-local,
/// aggregate-only telemetry. Capability hints are non-authoritative, and these
/// fields must never gain peer, endpoint, descriptor, producer, block, proof,
/// route, message, payload, client, user, or traffic dimensions.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct DirectoryProofGossipOutcome {
    state: DirectoryProofGossipPeerState,
    frames_attempted: usize,
    evidence_rejected: usize,
    result: DirectoryProofGossipResult,
}

impl DirectoryProofGossipOutcome {
    const fn negotiation_failed(result: DirectoryProofGossipResult) -> Self {
        Self {
            state: DirectoryProofGossipPeerState::NegotiationFailed,
            frames_attempted: 0,
            evidence_rejected: 0,
            result,
        }
    }

    const fn capability_checked(self) -> bool {
        !matches!(self.state, DirectoryProofGossipPeerState::NotChecked)
    }

    const fn capable(self) -> bool {
        matches!(self.state, DirectoryProofGossipPeerState::Attempted)
    }

    const fn attempted(self) -> bool {
        matches!(self.state, DirectoryProofGossipPeerState::Attempted)
    }

    const fn accepted(self) -> bool {
        matches!(self.result, DirectoryProofGossipResult::Accepted)
    }
}

/// Fixed phase of a mandatory compatibility gossip failure.
///
/// [DISCOVERY-GOSSIP-ISOLATION 2026-07-28 by Codex] Typed phases prevent URLs
/// or peer-controlled text from entering status, logs, or audit events.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DiscoveryGossipPhase {
    Peer,
    AnnounceRequest,
    AnnounceStatus,
    SnapshotRequest,
    SnapshotStatus,
    SnapshotResponse,
}

impl DiscoveryGossipPhase {
    const fn as_str(self) -> &'static str {
        match self {
            Self::Peer => "peer",
            Self::AnnounceRequest => "announce_request",
            Self::AnnounceStatus => "announce_status",
            Self::SnapshotRequest => "snapshot_request",
            Self::SnapshotStatus => "snapshot_status",
            Self::SnapshotResponse => "snapshot_response",
        }
    }
}

/// Privacy-safe class of a mandatory gossip failure.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DiscoveryGossipFailureKind {
    Timeout,
    Connect,
    Http(u16),
    HttpStatus,
    Decode,
    Body,
    Request,
    BoundedResponse(BoundedHttpResponseError),
    Unknown,
}

/// Typed internal failure retained by a per-peer report.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct DiscoveryGossipFailure {
    phase: DiscoveryGossipPhase,
    kind: DiscoveryGossipFailureKind,
}

impl DiscoveryGossipFailure {
    const fn peer_timeout() -> Self {
        Self {
            phase: DiscoveryGossipPhase::Peer,
            kind: DiscoveryGossipFailureKind::Timeout,
        }
    }

    fn from_reqwest(phase: DiscoveryGossipPhase, error: &reqwest::Error) -> Self {
        let kind = if error.is_timeout() {
            DiscoveryGossipFailureKind::Timeout
        } else if error.is_connect() {
            DiscoveryGossipFailureKind::Connect
        } else if error.is_status() {
            error
                .status()
                .map_or(DiscoveryGossipFailureKind::HttpStatus, |status| {
                    DiscoveryGossipFailureKind::Http(status.as_u16())
                })
        } else if error.is_decode() {
            DiscoveryGossipFailureKind::Decode
        } else if error.is_body() {
            DiscoveryGossipFailureKind::Body
        } else if error.is_request() {
            DiscoveryGossipFailureKind::Request
        } else {
            DiscoveryGossipFailureKind::Unknown
        };
        Self { phase, kind }
    }

    const fn from_bounded_response(
        phase: DiscoveryGossipPhase,
        error: BoundedHttpResponseError,
    ) -> Self {
        Self {
            phase,
            kind: DiscoveryGossipFailureKind::BoundedResponse(error),
        }
    }

    fn bucket(self) -> String {
        self.to_string()
    }
}

impl std::fmt::Display for DiscoveryGossipFailure {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(formatter, "{}_", self.phase.as_str())?;
        match self.kind {
            DiscoveryGossipFailureKind::Timeout => formatter.write_str("timeout"),
            DiscoveryGossipFailureKind::Connect => formatter.write_str("connect"),
            DiscoveryGossipFailureKind::Http(status) => write!(formatter, "http_{status}"),
            DiscoveryGossipFailureKind::HttpStatus => formatter.write_str("http_status"),
            DiscoveryGossipFailureKind::Decode => formatter.write_str("decode"),
            DiscoveryGossipFailureKind::Body => formatter.write_str("body"),
            DiscoveryGossipFailureKind::Request => formatter.write_str("request"),
            DiscoveryGossipFailureKind::BoundedResponse(error) => {
                formatter.write_str(error.as_str())
            }
            DiscoveryGossipFailureKind::Unknown => formatter.write_str("unknown"),
        }
    }
}

/// Unique verified node identities observed for canonical gossip URLs.
///
/// [DISCOVERY-IDENTITY-AMBIGUITY 2026-07-28 by Codex] Signed descriptors may
/// independently claim the same endpoint. Such a collision is not enough to
/// choose either identity, so the URL remains ambiguous for this hint set and
/// proof selection uses its bounded identity-agnostic fallback.
#[derive(Debug, Default)]
struct DiscoveryPeerIdentityHints {
    by_url: HashMap<String, Option<[u8; 32]>>,
}

impl DiscoveryPeerIdentityHints {
    fn observe_verified(&mut self, url: String, node_id: [u8; 32]) {
        match self.by_url.entry(url) {
            std::collections::hash_map::Entry::Vacant(entry) => {
                entry.insert(Some(node_id));
            }
            std::collections::hash_map::Entry::Occupied(mut entry) => {
                if entry.get().as_ref() != Some(&node_id) {
                    entry.insert(None);
                }
            }
        }
    }

    fn unique_node_id(&self, url: &str) -> Option<[u8; 32]> {
        self.by_url.get(url).copied().flatten()
    }
}

/// Immutable dependencies and policy for one outbound gossip round.
///
/// [DISCOVERY-GOSSIP-ISOLATION 2026-07-28 by Codex] Keeping these values in a
/// borrowed execution context prevents long parameter lists and guarantees
/// every concurrently polled peer receives the same limits and proof set.
#[derive(Clone, Copy)]
struct DiscoveryGossipExecution<'a> {
    client: &'a reqwest::Client,
    peer_store: &'a PeerStore,
    directory_announcements: &'a [DirectoryReplicaGossipAnnouncement],
    /// Verified `PeerStore` identity hints keyed by canonical gossip URL.
    ///
    /// [DIRECTORY-PROOF-DIVERSITY 2026-07-28 by Codex] This remains a local
    /// optimization only. Missing or stale hints cannot grant trust; they only
    /// decide whether a receiver's own producer proof is skipped.
    peer_identity_hints: Option<&'a DiscoveryPeerIdentityHints>,
    now: u64,
    snapshot_limit: u16,
    peer_timeout: Duration,
}

/// Complete result of one outbound peer gossip attempt.
///
/// [GOSSIP-OUTCOME-INTEGRITY 2026-07-28 by Codex] Optional proof telemetry is
/// retained even when the mandatory legacy descriptor/snapshot exchange fails.
/// The error renders as a bounded phase bucket from typed local variants;
/// it must never contain a URL, peer id, descriptor, proof, payload, or client.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct DiscoveryPeerGossipReport {
    directory_proof: DirectoryProofGossipOutcome,
    legacy_error: Option<DiscoveryGossipFailure>,
}

/// Process-local accumulator for one outbound gossip round.
///
/// This owns the counter fan-in so the task loop cannot accidentally count a
/// proof only when the later legacy exchange succeeds. All fields remain
/// aggregate control-plane observations without peer or traffic dimensions.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct DiscoveryGossipRoundAccumulator {
    attempted: usize,
    succeeded: usize,
    directory_proof: PeerStoreDirectoryProofGossipRound,
    last_failure_reason: Option<DiscoveryGossipFailure>,
}

impl DiscoveryGossipRoundAccumulator {
    fn observe(&mut self, report: DiscoveryPeerGossipReport) {
        self.attempted = self.attempted.saturating_add(1);

        let proof = report.directory_proof;
        self.directory_proof.capability_checked = self
            .directory_proof
            .capability_checked
            .saturating_add(usize::from(proof.capability_checked()));
        self.directory_proof.capable = self
            .directory_proof
            .capable
            .saturating_add(usize::from(proof.capable()));
        self.directory_proof.peers_attempted = self
            .directory_proof
            .peers_attempted
            .saturating_add(usize::from(proof.attempted()));
        self.directory_proof.frames_attempted = self
            .directory_proof
            .frames_attempted
            .saturating_add(proof.frames_attempted);
        self.directory_proof.accepted = self
            .directory_proof
            .accepted
            .saturating_add(usize::from(proof.accepted()));
        self.directory_proof.evidence_rejected = self
            .directory_proof
            .evidence_rejected
            .saturating_add(proof.evidence_rejected);
        match proof.result {
            DirectoryProofGossipResult::ReplicaUnavailable => {
                self.directory_proof.replica_unavailable =
                    self.directory_proof.replica_unavailable.saturating_add(1);
            }
            DirectoryProofGossipResult::RateLimited => {
                self.directory_proof.rate_limited =
                    self.directory_proof.rate_limited.saturating_add(1);
            }
            DirectoryProofGossipResult::ProtocolRejected => {
                self.directory_proof.protocol_rejected =
                    self.directory_proof.protocol_rejected.saturating_add(1);
            }
            DirectoryProofGossipResult::TransportFailed => {
                self.directory_proof.transport_failed =
                    self.directory_proof.transport_failed.saturating_add(1);
            }
            DirectoryProofGossipResult::NotAttempted
            | DirectoryProofGossipResult::Accepted
            | DirectoryProofGossipResult::EvidenceRejected => {}
        }

        if let Some(reason) = report.legacy_error {
            self.last_failure_reason = Some(reason);
        } else {
            self.succeeded = self.succeeded.saturating_add(1);
        }
    }

    const fn directory_proof_acceptance_percent(&self) -> usize {
        if self.directory_proof.capable == 0 {
            0
        } else {
            self.directory_proof.accepted.saturating_mul(100) / self.directory_proof.capable
        }
    }
}

/// Backward-compatible local peer-cache document.
///
/// `descriptor_snapshot` is flattened so legacy readers still see the exact
/// `NodeBootstrapSnapshot` top-level shape and ignore the additive routeability
/// and path-proof fields. Each recovery section has an independent signature
/// domain, allowing one invalid section to fail closed without discarding the
/// separately signed descriptors or other recovery evidence. This document is
/// local-only and must never be served by gossip.
#[derive(Debug, serde::Serialize, serde::Deserialize)]
struct PeerStoreCacheDocument {
    #[serde(flatten)]
    descriptor_snapshot: NodeBootstrapSnapshot,
    #[serde(default)]
    routeability_evidence_schema_version: u16,
    #[serde(default)]
    routeability_evidence: Vec<PeerStoreRouteabilityCacheEvidence>,
    #[serde(default)]
    route_quarantine_schema_version: u16,
    #[serde(default)]
    route_quarantine_evidence: Vec<PeerStoreRouteQuarantineCacheEvidence>,
    #[serde(default)]
    routeability_evidence_signer_node_id: Option<String>,
    #[serde(default)]
    routeability_evidence_signature_ed25519: Option<String>,
    #[serde(default)]
    two_hop_path_proof_schema_version: u16,
    #[serde(default)]
    two_hop_path_proof_events: Vec<PeerStoreTwoHopPathProofEvent>,
    #[serde(default)]
    two_hop_path_proof_signer_node_id: Option<String>,
    #[serde(default)]
    two_hop_path_proof_signature_ed25519: Option<String>,
    #[serde(default)]
    three_hop_path_proof_schema_version: u16,
    #[serde(default)]
    three_hop_path_proof_events: Vec<PeerStoreTwoHopPathProofEvent>,
    #[serde(default)]
    three_hop_path_proof_signer_node_id: Option<String>,
    #[serde(default)]
    three_hop_path_proof_signature_ed25519: Option<String>,
    #[serde(default)]
    verified_client_delivery_schema_version: u16,
    #[serde(default)]
    verified_client_delivery_generation: u64,
    #[serde(default)]
    verified_client_delivery_evidence: Option<PeerStoreVerifiedClientDeliveryCacheEvidence>,
    #[serde(default)]
    verified_client_delivery_signer_node_id: Option<String>,
    #[serde(default)]
    verified_client_delivery_signature_ed25519: Option<String>,
    /// Portable certificates remain self-authenticating through their pinned
    /// attestor signatures; this local-only section adds no host authority.
    #[serde(default)]
    route_domain_certificate_schema_version: u16,
    #[serde(default)]
    route_domain_certificates: Vec<RouteDomainAttestationCertificateV1>,
}

/// Aggregate result of one durable peer-cache write.
///
/// [THREE-HOP-SIGNED-RECOVERY 2026-08-02 by Codex] A named report replaces the
/// positional tuple so adding independently signed recovery sections cannot
/// silently swap counters at call sites.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PeerStoreCachePersistReport {
    two_hop_events: usize,
    two_hop_stability_ready: bool,
    three_hop_events: usize,
    three_hop_stability_ready: bool,
    route_domain_certificates: usize,
    client_deliveries: u64,
    client_delivery_generation: u64,
}

/// Durable state reached by one peer-cache persistence attempt.
///
/// [PEER-CACHE-RETRY-STATE 2026-08-12 by Codex] `Deferred` is not an error: it
/// means the generation intentionally remained pending because its configured
/// external delivery witness was not yet protected. Callers must not log it as
/// persisted or clear retry state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PeerStoreCachePersistOutcome {
    Persisted,
    Deferred,
}

impl PeerStoreCacheDocument {
    fn new(
        descriptor_snapshot: NodeBootstrapSnapshot,
        routeability_evidence: Vec<PeerStoreRouteabilityCacheEvidence>,
        route_quarantine_evidence: Vec<PeerStoreRouteQuarantineCacheEvidence>,
        two_hop_path_proof_events: Vec<PeerStoreTwoHopPathProofEvent>,
        three_hop_path_proof_events: Vec<PeerStoreTwoHopPathProofEvent>,
        route_domain_certificates: Vec<RouteDomainAttestationCertificateV1>,
        verified_client_delivery_generation: u64,
        verified_client_delivery_evidence: Option<PeerStoreVerifiedClientDeliveryCacheEvidence>,
        identity: &IdentityKeyPair,
    ) -> Result<Self> {
        let mut document = Self {
            descriptor_snapshot,
            routeability_evidence_schema_version: ROUTEABILITY_CACHE_EVIDENCE_SCHEMA_VERSION,
            routeability_evidence,
            route_quarantine_schema_version: ROUTE_QUARANTINE_CACHE_SCHEMA_VERSION,
            route_quarantine_evidence,
            routeability_evidence_signer_node_id: None,
            routeability_evidence_signature_ed25519: None,
            two_hop_path_proof_schema_version: TWO_HOP_PATH_PROOF_CACHE_SCHEMA_VERSION,
            two_hop_path_proof_events,
            two_hop_path_proof_signer_node_id: None,
            two_hop_path_proof_signature_ed25519: None,
            three_hop_path_proof_schema_version: THREE_HOP_PATH_PROOF_CACHE_SCHEMA_VERSION,
            three_hop_path_proof_events,
            three_hop_path_proof_signer_node_id: None,
            three_hop_path_proof_signature_ed25519: None,
            verified_client_delivery_schema_version: VERIFIED_CLIENT_DELIVERY_CACHE_SCHEMA_VERSION,
            verified_client_delivery_generation,
            verified_client_delivery_evidence,
            verified_client_delivery_signer_node_id: None,
            verified_client_delivery_signature_ed25519: None,
            route_domain_certificate_schema_version: ROUTE_DOMAIN_CERTIFICATE_CACHE_SCHEMA_VERSION,
            route_domain_certificates,
        };
        let signing_bytes = document
            .routeability_evidence_signing_bytes()
            .map_err(ServerError::internal)?;
        document.routeability_evidence_signer_node_id =
            Some(hex::encode(identity.public_key_bytes()));
        document.routeability_evidence_signature_ed25519 =
            Some(hex::encode(identity.sign(&signing_bytes)));
        let proof_signing_bytes = document
            .two_hop_path_proof_signing_bytes()
            .map_err(ServerError::internal)?;
        document.two_hop_path_proof_signer_node_id = Some(hex::encode(identity.public_key_bytes()));
        document.two_hop_path_proof_signature_ed25519 =
            Some(hex::encode(identity.sign(&proof_signing_bytes)));
        // [THREE-HOP-SIGNED-RECOVERY 2026-08-02 by Codex] Three-hop aggregate
        // evidence uses an independent signing domain so tampering cannot
        // invalidate descriptors, routeability, or the two-hop admission cache.
        let three_hop_signing_bytes = document
            .three_hop_path_proof_signing_bytes()
            .map_err(ServerError::internal)?;
        document.three_hop_path_proof_signer_node_id =
            Some(hex::encode(identity.public_key_bytes()));
        document.three_hop_path_proof_signature_ed25519 =
            Some(hex::encode(identity.sign(&three_hop_signing_bytes)));
        let client_delivery_signing_bytes = document
            .verified_client_delivery_signing_bytes()
            .map_err(ServerError::internal)?;
        document.verified_client_delivery_signer_node_id =
            Some(hex::encode(identity.public_key_bytes()));
        document.verified_client_delivery_signature_ed25519 =
            Some(hex::encode(identity.sign(&client_delivery_signing_bytes)));
        Ok(document)
    }

    fn from_json_bytes(bytes: &[u8]) -> std::result::Result<Self, String> {
        if bytes.len() > DISCOVERY_SNAPSHOT_MAX_BYTES {
            return Err(format!(
                "peer cache exceeds {} bytes",
                DISCOVERY_SNAPSHOT_MAX_BYTES
            ));
        }
        let document: Self =
            serde_json::from_slice(bytes).map_err(|error| format!("peer cache json: {error}"))?;
        document
            .descriptor_snapshot
            .validate_schema()
            .map_err(|error| format!("peer cache descriptor snapshot: {error}"))?;
        let evidence_version_valid = (document.routeability_evidence.is_empty()
            && document.routeability_evidence_schema_version == 0)
            || matches!(
                document.routeability_evidence_schema_version,
                ROUTEABILITY_CACHE_EVIDENCE_LEGACY_SCHEMA_VERSION
                    | ROUTEABILITY_CACHE_EVIDENCE_SCHEMA_VERSION
            );
        if !evidence_version_valid {
            return Err(format!(
                "unsupported routeability evidence schema version: {}",
                document.routeability_evidence_schema_version
            ));
        }
        let quarantine_version_valid = match document.routeability_evidence_schema_version {
            ROUTEABILITY_CACHE_EVIDENCE_SCHEMA_VERSION => {
                document.route_quarantine_schema_version
                    == ROUTE_QUARANTINE_CACHE_SCHEMA_VERSION
            }
            _ => {
                document.route_quarantine_schema_version == 0
                    && document.route_quarantine_evidence.is_empty()
            }
        };
        if !quarantine_version_valid {
            return Err(format!(
                "unsupported route quarantine cache schema version: {}",
                document.route_quarantine_schema_version
            ));
        }
        // [ROUTE-DOMAIN-CERTIFICATE-RECOVERY 2026-08-03 by Codex] Keep the
        // additive section backward compatible while rejecting count abuse
        // before any cryptographic work or PeerStore allocation is attempted.
        let route_domain_certificate_version_valid =
            (document.route_domain_certificates.is_empty()
                && document.route_domain_certificate_schema_version == 0)
                || document.route_domain_certificate_schema_version
                    == ROUTE_DOMAIN_CERTIFICATE_CACHE_SCHEMA_VERSION;
        if !route_domain_certificate_version_valid {
            return Err(format!(
                "unsupported route-domain certificate schema version: {}",
                document.route_domain_certificate_schema_version
            ));
        }
        if document.route_domain_certificates.len() > ROUTE_DOMAIN_CERTIFICATE_CACHE_MAX_ENTRIES {
            return Err(format!(
                "route-domain certificate cache exceeds {} entries",
                ROUTE_DOMAIN_CERTIFICATE_CACHE_MAX_ENTRIES
            ));
        }
        let proof_version_valid = (document.two_hop_path_proof_events.is_empty()
            && document.two_hop_path_proof_schema_version == 0)
            || document.two_hop_path_proof_schema_version
                == TWO_HOP_PATH_PROOF_CACHE_SCHEMA_VERSION;
        if !proof_version_valid {
            return Err(format!(
                "unsupported two-hop proof schema version: {}",
                document.two_hop_path_proof_schema_version
            ));
        }
        let three_hop_proof_version_valid = (document.three_hop_path_proof_events.is_empty()
            && document.three_hop_path_proof_schema_version == 0)
            || document.three_hop_path_proof_schema_version
                == THREE_HOP_PATH_PROOF_CACHE_SCHEMA_VERSION;
        if !three_hop_proof_version_valid {
            return Err(format!(
                "unsupported three-hop proof schema version: {}",
                document.three_hop_path_proof_schema_version
            ));
        }
        let client_delivery_version_valid = match document.verified_client_delivery_schema_version {
            0 => {
                document.verified_client_delivery_evidence.is_none()
                    && document.verified_client_delivery_generation == 0
            }
            VERIFIED_CLIENT_DELIVERY_CACHE_LEGACY_SCHEMA_VERSION => {
                document.verified_client_delivery_generation == 0
            }
            VERIFIED_CLIENT_DELIVERY_CACHE_SCHEMA_VERSION => {
                document.verified_client_delivery_generation > 0
            }
            _ => false,
        };
        if !client_delivery_version_valid {
            return Err(format!(
                "unsupported verified client delivery schema version: {}",
                document.verified_client_delivery_schema_version
            ));
        }
        Ok(document)
    }

    fn verify_routeability_evidence_signature(
        &self,
        identity: &IdentityKeyPair,
    ) -> std::result::Result<(), String> {
        if self.routeability_evidence.is_empty() && self.routeability_evidence_schema_version == 0 {
            return Ok(());
        }
        let expected_signer = hex::encode(identity.public_key_bytes());
        if self.routeability_evidence_signer_node_id.as_deref() != Some(&expected_signer) {
            return Err("routeability evidence signer mismatch".to_string());
        }
        let signature_hex = self
            .routeability_evidence_signature_ed25519
            .as_deref()
            .ok_or_else(|| "routeability evidence signature missing".to_string())?;
        let mut signature = [0u8; 64];
        hex::decode_to_slice(signature_hex, &mut signature)
            .map_err(|_| "routeability evidence signature encoding invalid".to_string())?;
        let public_key = IdentityPublicKey::from_bytes(&identity.public_key_bytes())
            .map_err(|_| "routeability evidence signer key invalid".to_string())?;
        let signing_bytes = self.routeability_evidence_signing_bytes()?;
        public_key
            .verify(&signing_bytes, &signature)
            .map_err(|_| "routeability evidence signature invalid".to_string())
    }

    fn routeability_evidence_signing_bytes(&self) -> std::result::Result<Vec<u8>, String> {
        let encoded = match self.routeability_evidence_schema_version {
            ROUTEABILITY_CACHE_EVIDENCE_LEGACY_SCHEMA_VERSION => bincode::serialize(&(
                "aeronyx-peer-cache-routeability-v1",
                self.descriptor_snapshot.generated_at,
                self.routeability_evidence_schema_version,
                &self.routeability_evidence,
            )),
            ROUTEABILITY_CACHE_EVIDENCE_SCHEMA_VERSION => bincode::serialize(&(
                "aeronyx-peer-cache-routeability-v2",
                self.descriptor_snapshot.generated_at,
                self.routeability_evidence_schema_version,
                &self.routeability_evidence,
                self.route_quarantine_schema_version,
                &self.route_quarantine_evidence,
            )),
            version => return Err(format!("unsupported routeability evidence schema: {version}")),
        };
        encoded
        .map_err(|error| format!("routeability evidence signing bytes: {error}"))
    }

    /// Returns an opaque digest of the exact independently signed route-state
    /// section, including active quarantine in cache schema v2.
    ///
    /// [ROUTE-STATE-ROLLBACK-ANCHOR 2026-08-21 by Codex] The local monotonic
    /// anchor commits to this digest, never to decoded endpoints or failure
    /// details. Binding signer and signature prevents an unsigned replacement
    /// from sharing the same anchor state even if its payload bytes match.
    fn route_state_digest(&self) -> std::result::Result<String, String> {
        let signer_hex = self
            .routeability_evidence_signer_node_id
            .as_deref()
            .ok_or_else(|| "route state signer missing".to_string())?;
        let signature_hex = self
            .routeability_evidence_signature_ed25519
            .as_deref()
            .ok_or_else(|| "route state signature missing".to_string())?;
        let mut signer = [0u8; 32];
        hex::decode_to_slice(signer_hex, &mut signer)
            .map_err(|_| "route state signer encoding invalid".to_string())?;
        let mut signature = [0u8; 64];
        hex::decode_to_slice(signature_hex, &mut signature)
            .map_err(|_| "route state signature encoding invalid".to_string())?;
        let signing_bytes = self.routeability_evidence_signing_bytes()?;

        let mut hasher = Sha256::new();
        hasher.update(b"AeroNyx-PeerCache-RouteStateDigest-v1");
        let signing_bytes_len = u64::try_from(signing_bytes.len())
            .map_err(|_| "route state signing bytes length invalid".to_string())?;
        hasher.update(signing_bytes_len.to_be_bytes());
        hasher.update(signing_bytes);
        hasher.update(signer);
        hasher.update(signature);
        Ok(hex::encode(hasher.finalize()))
    }

    fn verify_two_hop_path_proof_signature(
        &self,
        identity: &IdentityKeyPair,
    ) -> std::result::Result<(), String> {
        if self.two_hop_path_proof_events.is_empty() && self.two_hop_path_proof_schema_version == 0
        {
            return Ok(());
        }
        let expected_signer = hex::encode(identity.public_key_bytes());
        if self.two_hop_path_proof_signer_node_id.as_deref() != Some(&expected_signer) {
            return Err("two-hop proof signer mismatch".to_string());
        }
        let signature_hex = self
            .two_hop_path_proof_signature_ed25519
            .as_deref()
            .ok_or_else(|| "two-hop proof signature missing".to_string())?;
        let mut signature = [0u8; 64];
        hex::decode_to_slice(signature_hex, &mut signature)
            .map_err(|_| "two-hop proof signature encoding invalid".to_string())?;
        let public_key = IdentityPublicKey::from_bytes(&identity.public_key_bytes())
            .map_err(|_| "two-hop proof signer key invalid".to_string())?;
        let signing_bytes = self.two_hop_path_proof_signing_bytes()?;
        public_key
            .verify(&signing_bytes, &signature)
            .map_err(|_| "two-hop proof signature invalid".to_string())
    }

    fn two_hop_path_proof_signing_bytes(&self) -> std::result::Result<Vec<u8>, String> {
        bincode::serialize(&(
            "aeronyx-peer-cache-two-hop-proof-v1",
            self.descriptor_snapshot.generated_at,
            self.two_hop_path_proof_schema_version,
            &self.two_hop_path_proof_events,
        ))
        .map_err(|error| format!("two-hop proof signing bytes: {error}"))
    }

    fn two_hop_path_proof_digest(&self) -> std::result::Result<String, String> {
        Ok(hex::encode(Sha256::digest(
            self.two_hop_path_proof_signing_bytes()?,
        )))
    }

    fn verify_three_hop_path_proof_signature(
        &self,
        identity: &IdentityKeyPair,
    ) -> std::result::Result<(), String> {
        if self.three_hop_path_proof_events.is_empty()
            && self.three_hop_path_proof_schema_version == 0
        {
            return Ok(());
        }
        let expected_signer = hex::encode(identity.public_key_bytes());
        if self.three_hop_path_proof_signer_node_id.as_deref() != Some(&expected_signer) {
            return Err("three-hop proof signer mismatch".to_string());
        }
        let signature_hex = self
            .three_hop_path_proof_signature_ed25519
            .as_deref()
            .ok_or_else(|| "three-hop proof signature missing".to_string())?;
        let mut signature = [0u8; 64];
        hex::decode_to_slice(signature_hex, &mut signature)
            .map_err(|_| "three-hop proof signature encoding invalid".to_string())?;
        let public_key = IdentityPublicKey::from_bytes(&identity.public_key_bytes())
            .map_err(|_| "three-hop proof signer key invalid".to_string())?;
        let signing_bytes = self.three_hop_path_proof_signing_bytes()?;
        public_key
            .verify(&signing_bytes, &signature)
            .map_err(|_| "three-hop proof signature invalid".to_string())
    }

    fn three_hop_path_proof_signing_bytes(&self) -> std::result::Result<Vec<u8>, String> {
        bincode::serialize(&(
            "aeronyx-peer-cache-three-hop-proof-v1",
            self.descriptor_snapshot.generated_at,
            self.three_hop_path_proof_schema_version,
            &self.three_hop_path_proof_events,
        ))
        .map_err(|error| format!("three-hop proof signing bytes: {error}"))
    }

    fn three_hop_path_proof_digest(&self) -> std::result::Result<String, String> {
        Ok(hex::encode(Sha256::digest(
            self.three_hop_path_proof_signing_bytes()?,
        )))
    }

    fn verify_verified_client_delivery_signature(
        &self,
        identity: &IdentityKeyPair,
    ) -> std::result::Result<(), String> {
        if self.verified_client_delivery_evidence.is_none()
            && self.verified_client_delivery_schema_version == 0
        {
            return Ok(());
        }
        let expected_signer = hex::encode(identity.public_key_bytes());
        if self.verified_client_delivery_signer_node_id.as_deref() != Some(&expected_signer) {
            return Err("verified client delivery signer mismatch".to_string());
        }
        let signature_hex = self
            .verified_client_delivery_signature_ed25519
            .as_deref()
            .ok_or_else(|| "verified client delivery signature missing".to_string())?;
        let mut signature = [0u8; 64];
        hex::decode_to_slice(signature_hex, &mut signature)
            .map_err(|_| "verified client delivery signature encoding invalid".to_string())?;
        let public_key = IdentityPublicKey::from_bytes(&identity.public_key_bytes())
            .map_err(|_| "verified client delivery signer key invalid".to_string())?;
        let signing_bytes = self.verified_client_delivery_signing_bytes()?;
        public_key
            .verify(&signing_bytes, &signature)
            .map_err(|_| "verified client delivery signature invalid".to_string())
    }

    fn verified_client_delivery_signing_bytes(&self) -> std::result::Result<Vec<u8>, String> {
        match self.verified_client_delivery_schema_version {
            VERIFIED_CLIENT_DELIVERY_CACHE_LEGACY_SCHEMA_VERSION => bincode::serialize(&(
                "aeronyx-peer-cache-verified-client-delivery-v1",
                self.descriptor_snapshot.generated_at,
                self.verified_client_delivery_schema_version,
                self.verified_client_delivery_evidence,
            )),
            VERIFIED_CLIENT_DELIVERY_CACHE_SCHEMA_VERSION => bincode::serialize(&(
                "aeronyx-peer-cache-verified-client-delivery-v2",
                self.descriptor_snapshot.generated_at,
                self.verified_client_delivery_schema_version,
                self.verified_client_delivery_generation,
                self.verified_client_delivery_evidence,
            )),
            version => {
                return Err(format!(
                    "verified client delivery signing schema unsupported: {version}"
                ));
            }
        }
        .map_err(|error| format!("verified client delivery signing bytes: {error}"))
    }

    fn to_json_pretty(&self) -> Result<Vec<u8>> {
        let bytes = serde_json::to_vec_pretty(self)
            .map_err(|error| ServerError::internal(format!("peer cache json: {error}")))?;
        if bytes.len() > DISCOVERY_SNAPSHOT_MAX_BYTES {
            return Err(ServerError::internal(format!(
                "peer cache exceeds {} bytes",
                DISCOVERY_SNAPSHOT_MAX_BYTES
            )));
        }
        Ok(bytes)
    }
}

/// Independent signed local high-water mark for aggregate delivery evidence.
///
/// The anchor intentionally repeats only the cache generation, cache time,
/// aggregate count, and latest verification time. It contains no route,
/// endpoint, peer pair, sender, receiver, message id, payload commitment, or
/// ciphertext. Because it is host-local, it detects single-file rollback but
/// cannot detect a whole-host snapshot rollback that also replaces the anchor.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
struct PeerStoreVerifiedClientDeliveryAnchor {
    contract_version: String,
    cache_generation: u64,
    cache_generated_at: u64,
    evidence: Option<PeerStoreVerifiedClientDeliveryCacheEvidence>,
    /// Opaque digest of signed routeability plus active quarantine state.
    #[serde(default)]
    route_state_digest: Option<String>,
    /// Opaque digest of the independently signed two-hop proof section.
    #[serde(default)]
    two_hop_path_proof_digest: Option<String>,
    /// Opaque digest of the independently signed three-hop proof section.
    #[serde(default)]
    three_hop_path_proof_digest: Option<String>,
    signer_node_id: String,
    signature_ed25519: String,
}

impl PeerStoreVerifiedClientDeliveryAnchor {
    fn new(document: &PeerStoreCacheDocument, identity: &IdentityKeyPair) -> Result<Self> {
        let mut anchor = Self {
            contract_version: VERIFIED_CLIENT_DELIVERY_ANCHOR_CONTRACT.to_string(),
            cache_generation: document.verified_client_delivery_generation,
            cache_generated_at: document.descriptor_snapshot.generated_at,
            evidence: document.verified_client_delivery_evidence,
            route_state_digest: Some(
                document
                    .route_state_digest()
                    .map_err(ServerError::internal)?,
            ),
            two_hop_path_proof_digest: Some(
                document
                    .two_hop_path_proof_digest()
                    .map_err(ServerError::internal)?,
            ),
            three_hop_path_proof_digest: Some(
                document
                    .three_hop_path_proof_digest()
                    .map_err(ServerError::internal)?,
            ),
            signer_node_id: hex::encode(identity.public_key_bytes()),
            signature_ed25519: String::new(),
        };
        if anchor.cache_generation == 0 {
            return Err(ServerError::internal(
                "verified client delivery anchor generation must be positive",
            ));
        }
        anchor.signature_ed25519 =
            hex::encode(identity.sign(&anchor.signing_bytes().map_err(ServerError::internal)?));
        Ok(anchor)
    }

    fn from_json_bytes(bytes: &[u8]) -> std::result::Result<Self, String> {
        if bytes.len() > VERIFIED_CLIENT_DELIVERY_ANCHOR_MAX_BYTES {
            return Err(format!(
                "verified client delivery anchor exceeds {} bytes",
                VERIFIED_CLIENT_DELIVERY_ANCHOR_MAX_BYTES
            ));
        }
        let anchor: Self = serde_json::from_slice(bytes)
            .map_err(|error| format!("verified client delivery anchor json: {error}"))?;
        if !matches!(
            anchor.contract_version.as_str(),
            VERIFIED_CLIENT_DELIVERY_ANCHOR_LEGACY_CONTRACT
                | VERIFIED_CLIENT_DELIVERY_ANCHOR_PREVIOUS_CONTRACT
                | VERIFIED_CLIENT_DELIVERY_ANCHOR_CONTRACT
        ) {
            return Err("verified client delivery anchor contract unsupported".to_string());
        }
        if anchor.cache_generation == 0 {
            return Err("verified client delivery anchor generation invalid".to_string());
        }
        if matches!(
            anchor.contract_version.as_str(),
            VERIFIED_CLIENT_DELIVERY_ANCHOR_PREVIOUS_CONTRACT
                | VERIFIED_CLIENT_DELIVERY_ANCHOR_CONTRACT
        ) {
            for digest in [
                anchor.two_hop_path_proof_digest.as_deref(),
                anchor.three_hop_path_proof_digest.as_deref(),
            ] {
                let digest =
                    digest.ok_or_else(|| "recovery anchor proof digest missing".to_string())?;
                let mut decoded = [0u8; 32];
                hex::decode_to_slice(digest, &mut decoded)
                    .map_err(|_| "recovery anchor proof digest encoding invalid".to_string())?;
            }
        }
        match anchor.contract_version.as_str() {
            VERIFIED_CLIENT_DELIVERY_ANCHOR_LEGACY_CONTRACT => {
                if anchor.route_state_digest.is_some()
                    || anchor.two_hop_path_proof_digest.is_some()
                    || anchor.three_hop_path_proof_digest.is_some()
                {
                    return Err("legacy recovery anchor contains unsupported digest".to_string());
                }
            }
            VERIFIED_CLIENT_DELIVERY_ANCHOR_PREVIOUS_CONTRACT => {
                if anchor.route_state_digest.is_some() {
                    return Err("v2 recovery anchor contains route-state digest".to_string());
                }
            }
            VERIFIED_CLIENT_DELIVERY_ANCHOR_CONTRACT => {
                let digest = anchor
                    .route_state_digest
                    .as_deref()
                    .ok_or_else(|| "recovery anchor route-state digest missing".to_string())?;
                let mut decoded = [0u8; 32];
                hex::decode_to_slice(digest, &mut decoded).map_err(|_| {
                    "recovery anchor route-state digest encoding invalid".to_string()
                })?;
            }
            _ => unreachable!("anchor contract checked above"),
        }
        Ok(anchor)
    }

    fn signing_bytes(&self) -> std::result::Result<Vec<u8>, String> {
        match self.contract_version.as_str() {
            VERIFIED_CLIENT_DELIVERY_ANCHOR_LEGACY_CONTRACT => bincode::serialize(&(
                "aeronyx-peer-cache-verified-client-delivery-anchor-v1",
                self.contract_version.as_str(),
                self.cache_generation,
                self.cache_generated_at,
                self.evidence,
            )),
            VERIFIED_CLIENT_DELIVERY_ANCHOR_PREVIOUS_CONTRACT => bincode::serialize(&(
                "aeronyx-peer-cache-recovery-anchor-v2",
                self.contract_version.as_str(),
                self.cache_generation,
                self.cache_generated_at,
                self.evidence,
                self.two_hop_path_proof_digest.as_deref(),
                self.three_hop_path_proof_digest.as_deref(),
            )),
            VERIFIED_CLIENT_DELIVERY_ANCHOR_CONTRACT => bincode::serialize(&(
                "aeronyx-peer-cache-recovery-anchor-v3",
                self.contract_version.as_str(),
                self.cache_generation,
                self.cache_generated_at,
                self.evidence,
                self.route_state_digest.as_deref(),
                self.two_hop_path_proof_digest.as_deref(),
                self.three_hop_path_proof_digest.as_deref(),
            )),
            _ => return Err("recovery anchor contract unsupported".to_string()),
        }
        .map_err(|error| format!("verified client delivery anchor signing bytes: {error}"))
    }

    fn verify(&self, identity: &IdentityKeyPair) -> std::result::Result<(), String> {
        let expected_signer = hex::encode(identity.public_key_bytes());
        if self.signer_node_id != expected_signer {
            return Err("verified client delivery anchor signer mismatch".to_string());
        }
        let mut signature = [0u8; 64];
        hex::decode_to_slice(&self.signature_ed25519, &mut signature).map_err(|_| {
            "verified client delivery anchor signature encoding invalid".to_string()
        })?;
        let public_key = IdentityPublicKey::from_bytes(&identity.public_key_bytes())
            .map_err(|_| "verified client delivery anchor signer key invalid".to_string())?;
        public_key
            .verify(&self.signing_bytes()?, &signature)
            .map_err(|_| "verified client delivery anchor signature invalid".to_string())
    }

    fn matches_document(&self, document: &PeerStoreCacheDocument) -> bool {
        self.cache_generation == document.verified_client_delivery_generation
            && self.cache_generated_at == document.descriptor_snapshot.generated_at
            && self.evidence == document.verified_client_delivery_evidence
    }

    fn matches_two_hop_path_proof_section(&self, document: &PeerStoreCacheDocument) -> bool {
        matches!(
            self.contract_version.as_str(),
            VERIFIED_CLIENT_DELIVERY_ANCHOR_PREVIOUS_CONTRACT
                | VERIFIED_CLIENT_DELIVERY_ANCHOR_CONTRACT
        )
            && self.cache_generation == document.verified_client_delivery_generation
            && self.cache_generated_at == document.descriptor_snapshot.generated_at
            && document.two_hop_path_proof_digest().is_ok_and(|digest| {
                self.two_hop_path_proof_digest.as_deref() == Some(digest.as_str())
            })
    }

    fn matches_three_hop_path_proof_section(&self, document: &PeerStoreCacheDocument) -> bool {
        matches!(
            self.contract_version.as_str(),
            VERIFIED_CLIENT_DELIVERY_ANCHOR_PREVIOUS_CONTRACT
                | VERIFIED_CLIENT_DELIVERY_ANCHOR_CONTRACT
        )
            && self.cache_generation == document.verified_client_delivery_generation
            && self.cache_generated_at == document.descriptor_snapshot.generated_at
            && document.three_hop_path_proof_digest().is_ok_and(|digest| {
                self.three_hop_path_proof_digest.as_deref() == Some(digest.as_str())
            })
    }

    fn matches_route_state_section(&self, document: &PeerStoreCacheDocument) -> bool {
        self.contract_version == VERIFIED_CLIENT_DELIVERY_ANCHOR_CONTRACT
            && self.cache_generation == document.verified_client_delivery_generation
            && self.cache_generated_at == document.descriptor_snapshot.generated_at
            && document.route_state_digest().is_ok_and(|digest| {
                self.route_state_digest.as_deref() == Some(digest.as_str())
            })
    }

    /// Returns a domain-separated opaque digest of the exact signed anchor.
    ///
    /// External witnesses receive this digest, never the embedded aggregate
    /// delivery count or verification time. Binding the signer and signature
    /// prevents two differently signed anchor documents from sharing witness
    /// state even if their canonical fields were otherwise equal.
    fn witness_digest(&self) -> std::result::Result<[u8; 32], String> {
        let mut signer = [0u8; 32];
        hex::decode_to_slice(&self.signer_node_id, &mut signer)
            .map_err(|_| "verified client delivery anchor signer encoding invalid".to_string())?;
        let mut signature = [0u8; 64];
        hex::decode_to_slice(&self.signature_ed25519, &mut signature).map_err(|_| {
            "verified client delivery anchor signature encoding invalid".to_string()
        })?;
        let mut hasher = Sha256::new();
        hasher.update(b"AeroNyx-VerifiedDeliveryAnchorWitnessDigest-v1");
        hasher.update(self.signing_bytes()?);
        hasher.update(signer);
        hasher.update(signature);
        Ok(hasher.finalize().into())
    }

    fn to_json_pretty(&self) -> Result<Vec<u8>> {
        let bytes = serde_json::to_vec_pretty(self).map_err(|error| {
            ServerError::internal(format!("verified client delivery anchor json: {error}"))
        })?;
        if bytes.len() > VERIFIED_CLIENT_DELIVERY_ANCHOR_MAX_BYTES {
            return Err(ServerError::internal(format!(
                "verified client delivery anchor exceeds {} bytes",
                VERIFIED_CLIENT_DELIVERY_ANCHOR_MAX_BYTES
            )));
        }
        Ok(bytes)
    }
}

#[derive(Debug, Clone)]
enum PeerStoreVerifiedClientDeliveryAnchorState {
    /// Compatibility path for direct parser callers and non-cache sources.
    NotChecked,
    Missing,
    Invalid,
    Verified(PeerStoreVerifiedClientDeliveryAnchor),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PeerStoreVerifiedClientDeliveryExternalWitnessDecision {
    /// No external witness policy is configured; local anchor behavior remains unchanged.
    Disabled,
    /// No local anchor exists yet. Only a genuinely fresh cache may bootstrap.
    Missing,
    /// The exact local anchor reached the configured accepted-response threshold.
    Protected,
    /// The local anchor was unavailable, adverse, or below threshold.
    Unprotected(&'static str),
}

impl PeerStoreVerifiedClientDeliveryAnchorState {
    fn protection_for(&self, document: &PeerStoreCacheDocument) -> &'static str {
        if document.verified_client_delivery_schema_version
            == VERIFIED_CLIENT_DELIVERY_CACHE_LEGACY_SCHEMA_VERSION
        {
            return match self {
                Self::NotChecked | Self::Missing => "legacy_unanchored",
                Self::Invalid => "anchor_invalid",
                Self::Verified(_) => "rollback_detected",
            };
        }
        if document.verified_client_delivery_schema_version == 0 {
            return "not_checked";
        }
        match self {
            Self::NotChecked => "not_checked",
            Self::Missing => "anchor_missing",
            Self::Invalid => "anchor_invalid",
            Self::Verified(anchor) => {
                if document.verified_client_delivery_generation < anchor.cache_generation {
                    "rollback_detected"
                } else if document.verified_client_delivery_generation > anchor.cache_generation {
                    "cache_ahead"
                } else if anchor.matches_document(document) {
                    "anchored"
                } else {
                    "anchor_conflict"
                }
            }
        }
    }

    fn two_hop_path_proof_protection_for(&self, document: &PeerStoreCacheDocument) -> &'static str {
        self.path_proof_protection_for(document, |anchor, document| {
            anchor.matches_two_hop_path_proof_section(document)
        })
    }

    fn three_hop_path_proof_protection_for(
        &self,
        document: &PeerStoreCacheDocument,
    ) -> &'static str {
        self.path_proof_protection_for(document, |anchor, document| {
            anchor.matches_three_hop_path_proof_section(document)
        })
    }

    /// Evaluates the signed routeability/quarantine snapshot against the
    /// monotonic local generation without exposing its digest.
    fn route_state_protection_for(&self, document: &PeerStoreCacheDocument) -> &'static str {
        match self {
            Self::NotChecked => "not_checked",
            Self::Missing => "anchor_missing",
            Self::Invalid => "anchor_invalid",
            Self::Verified(anchor) => {
                if document.verified_client_delivery_generation < anchor.cache_generation {
                    "rollback_detected"
                } else if document.verified_client_delivery_generation > anchor.cache_generation {
                    "cache_ahead"
                } else if anchor.contract_version != VERIFIED_CLIENT_DELIVERY_ANCHOR_CONTRACT {
                    "legacy_unanchored"
                } else if anchor.matches_route_state_section(document) {
                    "anchored"
                } else {
                    "anchor_conflict"
                }
            }
        }
    }

    /// Evaluates rollback protection independently from aggregate delivery
    /// evidence so one proof-anchor mismatch cannot discard the other proof
    /// section or valid descriptors.
    fn path_proof_protection_for(
        &self,
        document: &PeerStoreCacheDocument,
        matches_section: impl FnOnce(
            &PeerStoreVerifiedClientDeliveryAnchor,
            &PeerStoreCacheDocument,
        ) -> bool,
    ) -> &'static str {
        match self {
            Self::NotChecked => "not_checked",
            Self::Missing => "anchor_missing",
            Self::Invalid => "anchor_invalid",
            Self::Verified(anchor) => {
                if document.verified_client_delivery_generation < anchor.cache_generation {
                    "rollback_detected"
                } else if document.verified_client_delivery_generation > anchor.cache_generation {
                    "cache_ahead"
                } else if anchor.contract_version == VERIFIED_CLIENT_DELIVERY_ANCHOR_LEGACY_CONTRACT
                {
                    "legacy_unanchored"
                } else if matches_section(anchor, document) {
                    "anchored"
                } else {
                    "anchor_conflict"
                }
            }
        }
    }
}

/// Return the privacy-safe reason a persisted MemChain record must not enter
/// the in-memory recall index.
///
/// Sighted records retain backward compatibility: their content-addressed ID
/// is required, but legacy zero signatures remain accepted. Node-blind records
/// additionally require the authenticated owner's Ed25519 signature because
/// the node is not allowed to re-sign client ciphertext.
fn memchain_index_rejection_reason(record: &MemoryRecord) -> Option<&'static str> {
    if !record.verify_id() {
        return Some("record_id_mismatch");
    }

    if record.blind {
        let owner_key = match IdentityPublicKey::from_bytes(&record.owner) {
            Ok(key) => key,
            Err(_) => return Some("owner_key_invalid"),
        };
        if owner_key
            .verify(&record.record_id, &record.signature)
            .is_err()
        {
            return Some("owner_signature_invalid");
        }
    }

    None
}

