        let unique = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let path =
            std::env::temp_dir().join(format!("aeronyx-peer-cache-backup-restore-{unique}.json"));
        let path_str = path.to_string_lossy().to_string();
